const source = $('Prepare Phase 4 Candidate').item.json;
const raw = String($json?.choices?.[0]?.message?.content ?? '');

function unwrap(value) {
  const text = String(value ?? '').trim();
  if ((text.startsWith('```') || text.startsWith('~~~'))
      && (text.endsWith('```') || text.endsWith('~~~'))) {
    const firstLine = text.indexOf('\n');
    const closing = Math.max(text.lastIndexOf('```'), text.lastIndexOf('~~~'));
    return text.slice(firstLine + 1, closing).trim();
  }
  return text;
}

function canonical(value) {
  return String(value ?? '')
    .replace(/[\u200B-\u200F\u2060\uFEFF]/gu, '')
    .replace(/\*+/g, '')
    .replace(/[“”]/gu, '"')
    .replace(/[‘’]/gu, "'")
    .replace(/[–—]/gu, '-')
    .replace(/\s+/gu, ' ')
    .trim()
    .toLocaleLowerCase('en');
}

function isInsideCandidateBoundary(candidateQuote, evidenceQuote) {
  const candidate = canonical(candidateQuote);
  const evidence = canonical(evidenceQuote);
  return Boolean(candidate && evidence && (candidate.includes(evidence) || evidence.includes(candidate)));
}

function coversCompleteCandidateBoundary(candidateQuote, evidenceQuote) {
  const candidate = canonical(candidateQuote);
  const evidence = canonical(evidenceQuote);
  return Boolean(candidate && evidence && evidence.includes(candidate));
}

function hasCandidateActionOverlap(evidenceQuote) {
  const stopwords = new Set(['a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in', 'of', 'on', 'the', 'to', 'with']);
  const tokens = (value) => canonical(value).match(/[a-z0-9]+/gu) || [];
  const evidence = new Set(tokens(evidenceQuote));
  const identity = [...new Set([
    ...tokens(source.candidate_title),
    ...tokens(source.candidate_description),
  ].filter((token) => token.length > 2 && !stopwords.has(token)))];
  const overlap = identity.filter((token) => evidence.has(token)).length;
  return identity.length > 0 && overlap >= Math.min(2, identity.length);
}

function isExactArticleQuote(evidenceQuote) {
  const quote = String(evidenceQuote ?? '').trim();
  return Boolean(quote
    && !/\.\.\.|…/u.test(quote)
    && String(source.cleaned_content_text ?? '').includes(quote));
}

function restoreExactArticleQuote(quote) {
  const matchForm = (value) => String(value ?? '')
    .replace(/[\u200B-\u200F\u2060\uFEFF]/gu, '')
    .replace(/\*+/g, '')
    .replace(/\s+/gu, ' ')
    .trim()
    .toLocaleLowerCase('en');
  const requested = matchForm(quote);
  const article = String(source.cleaned_content_text ?? '');
  if (!requested || /\.\.\.|…/u.test(String(quote ?? ''))) return null;
  if (article.includes(String(quote ?? '').trim())) return String(quote).trim();
  const mapped = [];
  let normalized = '';
  let pendingSpace = false;
  for (let index = 0; index < article.length; index += 1) {
    const original = article[index];
    if (/[*\u200B-\u200F\u2060\uFEFF]/u.test(original)) continue;
    const converted = original.toLocaleLowerCase('en');
    if (/\s/u.test(converted)) {
      if (normalized && !pendingSpace) {
        normalized += ' ';
        mapped.push(index);
        pendingSpace = true;
      }
      continue;
    }
    pendingSpace = false;
    normalized += converted;
    mapped.push(index);
  }
  const start = normalized.indexOf(requested);
  if (start < 0) return null;
  return article.slice(mapped[start], mapped[start + requested.length - 1] + 1).trim();
}

function resolveRelativeWeekday(evidenceQuote, publicationDate, proposedDate) {
  const match = String(evidenceQuote ?? '').match(/\b(last\s+)?(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/iu);
  if (!match || !/^\d{4}-\d{2}-\d{2}$/.test(String(publicationDate ?? ''))) return null;
  const publication = new Date(String(publicationDate) + 'T00:00:00Z');
  if (Number.isNaN(publication.getTime())) return null;
  const weekdays = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const target = weekdays.indexOf(match[2].toLocaleLowerCase('en'));
  if (!match[1] && /^\d{4}-\d{2}-\d{2}$/.test(String(proposedDate ?? ''))) {
    const proposed = new Date(String(proposedDate) + 'T00:00:00Z');
    const distanceDays = (proposed.getTime() - publication.getTime()) / 86400000;
    if (!Number.isNaN(proposed.getTime())
        && proposed.getUTCDay() === target
        && Math.abs(distanceDays) <= 6) {
      return proposed.toISOString().slice(0, 10);
    }
  }
  let daysBack = (publication.getUTCDay() - target + 7) % 7;
  if (match[1] && daysBack === 0) daysBack = 7;
  publication.setUTCDate(publication.getUTCDate() - daysBack);
  return publication.toISOString().slice(0, 10);
}

function normalizeGroundedMonthDay(value, precision, evidenceQuote, publicationDate) {
  if (precision !== 'exact' || /^\d{4}-\d{2}-\d{2}$/.test(String(value ?? ''))) return value;
  const year = String(publicationDate ?? '').match(/^(\d{4})-/u)?.[1];
  if (!year) return value;
  const months = {
    january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
    july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
  };
  const proposed = canonical(value).match(/^([a-z]+)\s+(\d{1,2})$/u)
    || canonical(value).match(/^(\d{1,2})\s+([a-z]+)$/u);
  if (!proposed) return value;
  const monthName = /^\d/u.test(proposed[1]) ? proposed[2] : proposed[1];
  const dayText = /^\d/u.test(proposed[1]) ? proposed[1] : proposed[2];
  const month = months[monthName];
  const day = Number(dayText);
  const evidence = canonical(evidenceQuote);
  if (!month || day < 1 || day > 31
      || !evidence.includes(monthName)
      || !new RegExp(`\\b${day}\\b`, 'u').test(evidence)) return value;
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function normalizeGroundedMonth(value, precision, evidenceQuote, publicationDate) {
  if (precision !== 'month' || /^\d{4}-\d{2}$/.test(String(value ?? ''))) return value;
  const year = String(publicationDate ?? '').match(/^(\d{4})-/u)?.[1];
  if (!year) return value;
  const months = {
    january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
    july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
  };
  const monthName = canonical(value);
  const month = months[monthName];
  if (!month || !new RegExp(`\\b${monthName}\\b`, 'u').test(canonical(evidenceQuote))) return value;
  return `${year}-${String(month).padStart(2, '0')}`;
}

function timeReferenceCount(evidenceQuote) {
  const text = canonical(evidenceQuote);
  const patterns = [
    /\b(?:last\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/gu,
    /\b(?:last|this|next|earlier|later)\s+(?:week|month|year|summer|winter|spring|autumn|fall)\b/gu,
    /\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?\s+\d{1,2}\b/gu,
    /\b(?:in|during)\s+(?:january|february|march|april|may|june|july|august|september|october|november|december)\b/gu,
    /\b\d{4}-\d{2}-\d{2}\b/gu,
    /\b(?:in|during)\s+\d{4}\b/gu,
  ];
  return patterns.reduce((count, pattern) => count + [...text.matchAll(pattern)].length, 0);
}

function weekdayAnchorsCandidateStatement(evidenceQuote) {
  const identity = canonical(`${source.candidate_title ?? ''} ${source.candidate_description ?? ''}`);
  const evidence = canonical(evidenceQuote);
  const statementCandidate = /\b(?:offer|offers|offered|statement|remarks?|rebuke|rebukes|warn|warns|warned|urge|urges|urged|announce|announces|announced|say|says|said|state|states|stated)\b/u.test(identity);
  const weekdayStatement = /\b(?:said|stated|announced|reported|warned|urged)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/u.test(evidence);
  return statementCandidate && weekdayStatement;
}

function candidateSupportsEpistemicStatus(status) {
  const candidate = String(source.candidate_evidence_quote ?? '').trim();
  if (!candidate || !isExactArticleQuote(candidate)) return null;
  const text = canonical(candidate);
  if (status === 'reported' && /\b(?:said|stated|reported|told|announced|according to)\b/u.test(text)) return candidate;
  return null;
}

function isVagueExactDate(evidenceQuote, precision) {
  if (precision !== 'exact') return false;
  const text = canonical(evidenceQuote);
  const vague = /\b(?:last|this|next|earlier|later)\s+(?:week|month|year|summer|winter|spring|autumn|fall)\b/u.test(text);
  const exactAnchor = /\b(?:last\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/u.test(text)
    || /\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?\s+\d{1,2}\b/u.test(text)
    || /\b\d{4}-\d{2}-\d{2}\b/u.test(text);
  return vague && !exactAnchor;
}

let parsed = null;
try {
  parsed = JSON.parse(unwrap(raw).replace(
    /("epistemic_status"\s*:\s*)(confirmed|reported|alleged|planned|denied|unknown)(?=\s*[,}])/g,
    '$1"$2"',
  ));
} catch {
  parsed = null;
}

let policyReason = null;
let epistemicPolicyReason = null;
if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
  if (parsed.event_date_precision === 'day') parsed.event_date_precision = 'exact';
  const hasDate = typeof parsed.event_date === 'string' && parsed.event_date.trim();
  const dateQuote = typeof parsed.event_date_evidence_quote === 'string'
    ? parsed.event_date_evidence_quote.trim()
    : '';
  const restoredDateQuote = restoreExactArticleQuote(dateQuote);
  if (hasDate && restoredDateQuote) parsed.event_date_evidence_quote = restoredDateQuote;
  if (hasDate && !isInsideCandidateBoundary(source.candidate_evidence_quote, dateQuote)) {
    parsed.event_date = null;
    parsed.event_date_precision = 'unknown';
    parsed.event_date_evidence_quote = null;
    policyReason = 'The proposed date evidence was outside the candidate event boundary and was omitted.';
  } else if (hasDate
      && !coversCompleteCandidateBoundary(source.candidate_evidence_quote, dateQuote)
      && !hasCandidateActionOverlap(dateQuote)) {
    parsed.event_date = null;
    parsed.event_date_precision = 'unknown';
    parsed.event_date_evidence_quote = null;
    policyReason = 'The proposed date evidence did not cover the complete candidate boundary and was omitted.';
  } else if (hasDate && timeReferenceCount(dateQuote) > 1 && !weekdayAnchorsCandidateStatement(dateQuote)) {
    parsed.event_date = null;
    parsed.event_date_precision = 'unknown';
    parsed.event_date_evidence_quote = null;
    policyReason = 'The proposed date evidence contained multiple time references and could not safely identify the candidate event date.';
  } else if (hasDate && isVagueExactDate(dateQuote, parsed.event_date_precision)) {
    parsed.event_date = null;
    parsed.event_date_precision = 'unknown';
    parsed.event_date_evidence_quote = null;
    policyReason = 'The proposed exact date came only from a vague relative period and was omitted.';
  } else if (hasDate) {
    parsed.event_date = normalizeGroundedMonthDay(
      parsed.event_date,
      parsed.event_date_precision,
      dateQuote,
      source.publication_date,
    );
    parsed.event_date = normalizeGroundedMonth(
      parsed.event_date,
      parsed.event_date_precision,
      dateQuote,
      source.publication_date,
    );
    const resolved = resolveRelativeWeekday(dateQuote, source.publication_date, parsed.event_date);
    if (resolved) {
      parsed.event_date = resolved;
      parsed.event_date_precision = 'exact';
    }
  }

  const epistemicQuote = typeof parsed.epistemic_status_evidence_quote === 'string'
    ? parsed.epistemic_status_evidence_quote.trim()
    : '';
  const restoredEpistemicQuote = restoreExactArticleQuote(epistemicQuote);
  if (parsed.epistemic_status !== 'unknown' && restoredEpistemicQuote) {
    parsed.epistemic_status_evidence_quote = restoredEpistemicQuote;
  }
  if (parsed.epistemic_status !== 'unknown'
      && !isInsideCandidateBoundary(source.candidate_evidence_quote, epistemicQuote)) {
    const candidateQuote = candidateSupportsEpistemicStatus(parsed.epistemic_status);
    if (candidateQuote) {
      parsed.epistemic_status_evidence_quote = candidateQuote;
    } else {
      parsed.epistemic_status = 'unknown';
      parsed.epistemic_status_evidence_quote = null;
      epistemicPolicyReason = 'The proposed epistemic-status evidence was outside the candidate event boundary and was omitted.';
    }
  } else if (parsed.epistemic_status !== 'unknown' && !isExactArticleQuote(restoredEpistemicQuote)) {
    parsed.epistemic_status = 'unknown';
    parsed.epistemic_status_evidence_quote = null;
    epistemicPolicyReason = 'The proposed epistemic-status evidence was not exact source text and was omitted.';
  }
}

return [{json: {
  ...source,
  p4_date_raw_output: raw || null,
  p4_date_validated_output: parsed ? JSON.stringify(parsed) : raw || null,
  p4_date_policy_reason: policyReason,
  p4_epistemic_policy_reason: epistemicPolicyReason,
  p4_upstream_policy_reason: source.phase3_candidate_status === 'NEEDS_REVIEW'
    ? 'The Phase 3 candidate requires review, so the Phase 4 result cannot be marked valid automatically.'
    : null,
}}];

const actors = Array.isArray($json.p4_actor_candidates) ? $json.p4_actor_candidates : [];
const lastIndex = actors.length - 1;
const rules = [
  'Review actors only. The title is an identity label only.',
  'Use the candidate evidence quote only to define the event boundary. Judge each actor against its own evidence_quote in the complete cleaned article, and accept only when that quote directly shows a role in the same candidate event.',
  'Reject reporters, interviewers, commentators, analysts, officials who only discuss the event, and actors from background or related events. Do not use candidate description, the candidate evidence quote, outside knowledge, aliases, or normalization as proof of an actor.',
  `Return exactly ${actors.length} decisions with indexes 0 through ${lastIndex}.`,
  `Do not omit the final index ${lastIndex}. Before responding, verify every index in that range appears exactly once.`,
  'Return only {"decisions":[{"index":0,"decision":"ACCEPT","reason":null}]}; use REJECT with a concrete reason when unsupported.',
].join('\n');

return [{json: {
  ...$json,
  p4_actor_safeguard_prompt: rules
    + '\n\nEvent title:\n' + String($json.candidate_title ?? '')
    + '\n\nCandidate evidence scope:\n' + String($json.candidate_evidence_quote ?? '')
    + '\n\nActors:\n' + JSON.stringify(actors)
    + '\n\nComplete cleaned article:\n' + String($json.cleaned_content_text ?? ''),
}}];

const s=$('Validate Actors').item.json;
const raw=String($json?.choices?.[0]?.message?.content??'');
const reasons=[...(s.p4_review_reasons||[])],src=s.p4_actor_candidates||[],accepted=[];
const unwrap=x=>{const t=String(x??'').trim();if((t.startsWith('```')||t.startsWith('~~~'))&&(t.endsWith('```')||t.endsWith('~~~'))){const a=t.indexOf('\n'),b=Math.max(t.lastIndexOf('```'),t.lastIndexOf('~~~'));return t.slice(a+1,b).trim()}return t};
let status='NOT_RUN';
if(src.length){
  let p;try{p=JSON.parse(unwrap(raw))}catch{p=null}
  status='ACCEPT';
  const seen=new Set();
  if(!p||!Array.isArray(p.decisions)){status='FAILED';reasons.push('The actor safeguard failed or returned no usable decisions; unreviewed actors were omitted.')}
  else{
    for(const d of p.decisions){
      const validIndex=Number.isInteger(d?.index)&&d.index>=0&&d.index<src.length&&!seen.has(d.index);
      const validDecision=['ACCEPT','REJECT'].includes(d?.decision);
      const validReason=d?.decision==='ACCEPT'?d?.reason==null:typeof d?.reason==='string'&&d.reason.trim();
      if(!validIndex||!validDecision||!validReason){status='FAILED';continue}
      seen.add(d.index);
      if(d.decision==='ACCEPT')accepted.push(src[d.index]);
      else{if(status!=='FAILED')status='REJECT';reasons.push('The actor safeguard rejected an actor: '+d.reason.trim())}
    }
    const missing=src.length-seen.size;
    if(missing>0){status='FAILED';reasons.push('The actor safeguard returned incomplete decisions; '+missing+' unreviewed actor'+(missing===1?' was':'s were')+' omitted.')}
    else if(status==='FAILED')reasons.push('The actor safeguard returned invalid or duplicate decisions; only individually approved actors were retained.')
  }
}
return [{json:{...s,p4_actors:accepted,p4_actor_safeguard_status:status,p4_actor_safeguard_raw_output:raw||null,p4_review_reasons:reasons}}];

const source = $('Build Actor Prompt').item.json;
const raw = String($json?.choices?.[0]?.message?.content ?? '');
const reasons = [];

function canonical(value) {
  return String(value ?? '')
    .replace(/[\u200B-\u200F\u2060\uFEFF]/gu, '')
    .replace(/\*+/g, '')
    .replace(/[“”]/gu, '"')
    .replace(/[‘’]/gu, "'")
    .replace(/[–—]/gu, '-')
    .replace(/\s+/gu, ' ')
    .trim()
    .toLocaleLowerCase('en');
}

function unwrap(value) {
  const text = String(value ?? '').trim();
  if ((text.startsWith('```') || text.startsWith('~~~'))
      && (text.endsWith('```') || text.endsWith('~~~'))) {
    const firstLine = text.indexOf('\n');
    const closing = Math.max(text.lastIndexOf('```'), text.lastIndexOf('~~~'));
    return text.slice(firstLine + 1, closing).trim();
  }
  return text;
}

function isExactArticleQuote(quote) {
  const text = String(quote ?? '').trim();
  return Boolean(text
    && !/\.\.\.|…/u.test(text)
    && String(source.cleaned_content_text ?? '').includes(text));
}

function restoreExactArticleQuote(quote) {
  const matchForm = (value) => String(value ?? '')
    .replace(/[\u200B-\u200F\u2060\uFEFF]/gu, '')
    .replace(/\*+/g, '')
    .replace(/\s+/gu, ' ')
    .trim()
    .toLocaleLowerCase('en');
  const requested = matchForm(quote);
  const article = String(source.cleaned_content_text ?? '');
  if (!requested || /\.\.\.|…/u.test(String(quote ?? ''))) return null;
  if (article.includes(String(quote ?? '').trim())) return String(quote).trim();
  const mapped = [];
  let normalized = '';
  let pendingSpace = false;
  for (let index = 0; index < article.length; index += 1) {
    const original = article[index];
    if (/[*\u200B-\u200F\u2060\uFEFF]/u.test(original)) continue;
    const converted = original.toLocaleLowerCase('en');
    if (/\s/u.test(converted)) {
      if (normalized && !pendingSpace) {
        normalized += ' ';
        mapped.push(index);
        pendingSpace = true;
      }
      continue;
    }
    pendingSpace = false;
    normalized += converted;
    mapped.push(index);
  }
  const start = normalized.indexOf(requested);
  if (start < 0) return null;
  return article.slice(mapped[start], mapped[start + requested.length - 1] + 1).trim();
}

function correctedRole(role, name, evidenceQuote) {
  if (role !== 'source') return role;
  const actor = canonical(name).replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
  const reportingSubject = new RegExp(`\\b${actor}\\b(?:\\s*,?\\s*(?:has|have|had|also|who|which)){0,3}\\s+(?:said|says|stated|reported|claimed|confirmed|denied|told)\\b`, 'u');
  return reportingSubject.test(canonical(evidenceQuote)) ? role : 'participant';
}

function isInsideCandidateBoundary(evidenceQuote) {
  const candidate = canonical(source.candidate_evidence_quote);
  const evidence = canonical(evidenceQuote);
  return Boolean(candidate && evidence && (candidate.includes(evidence) || evidence.includes(candidate)));
}

function isBareNationalityAdjective(name) {
  return new Set([
    'american', 'british', 'chinese', 'french', 'german', 'indian', 'iranian',
    'iraqi', 'israeli', 'japanese', 'korean', 'pakistani', 'palestinian',
    'polish', 'russian', 'saudi', 'syrian', 'turkish', 'ukrainian',
  ]).has(canonical(name));
}

function isUnresolvedReference(name) {
  return /^(?:the|this|that|an?)\s+(?:official|minister|spokesperson|source|representative|person|leader)$/u.test(canonical(name));
}

function appearsOnlyInNeighboringTemporalClause(name, evidenceQuote) {
  const evidence = canonical(evidenceQuote);
  const actor = canonical(name).replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
  return new RegExp(`\\b(?:(?:\\d+|one|two|three|four|five|six|seven|eight|nine|ten)\\s+days?|a\\s+day|hours?|weeks?)\\s+(?:before|after)\\b[^.]*\\b${actor}\\b`, 'u')
    .test(evidence);
}

let parsed;
try { parsed = JSON.parse(unwrap(raw)); } catch { parsed = null; }

const actors = [];
if (!parsed || !Array.isArray(parsed.actors)) {
  reasons.push(raw
    ? 'The actor response was not valid JSON with an actors array.'
    : 'The actor request failed or returned no response.');
} else {
  for (const value of parsed.actors) {
    const name = String(value?.name ?? '').trim();
    const role = value?.role;
    const proposedEvidenceQuote = String(value?.evidence_quote ?? '').trim();
    const evidenceQuote = restoreExactArticleQuote(proposedEvidenceQuote);
    if (!name || !['source', 'recipient', 'participant'].includes(role)
        || !evidenceQuote || !isExactArticleQuote(evidenceQuote)) {
      reasons.push('A proposed actor was incomplete, truncated, or unsupported and was omitted.');
      continue;
    }
    if (!isInsideCandidateBoundary(evidenceQuote)) {
      reasons.push('A proposed actor used evidence outside the candidate event boundary and was omitted.');
      continue;
    }
    if (!canonical(evidenceQuote).includes(canonical(name))) {
      reasons.push('A proposed actor name was not explicit in its own evidence and was omitted.');
      continue;
    }
    if (isBareNationalityAdjective(name)) {
      reasons.push('A proposed actor was only a nationality adjective, not an explicit actor entity, and was omitted.');
      continue;
    }
    if (isUnresolvedReference(name)) {
      reasons.push('A proposed actor was an unresolved reference rather than an explicit actor entity and was omitted.');
      continue;
    }
    if (appearsOnlyInNeighboringTemporalClause(name, evidenceQuote)) {
      reasons.push('A proposed actor belonged to a neighboring event clause rather than the candidate event and was omitted.');
      continue;
    }
    const actor = {name, role: correctedRole(role, name, evidenceQuote), evidence_quote: evidenceQuote};
    if (!actors.some((existing) => JSON.stringify(existing) === JSON.stringify(actor))) {
      actors.push(actor);
    }
  }
}

return [{json: {
  ...source,
  p4_actor_candidates: actors,
  p4_actor_raw_output: raw || null,
  p4_review_reasons: reasons,
  p4_needs_safeguard: true,
}}];

const source = $('Build Location Prompt').item.json;
const raw = String($json?.choices?.[0]?.message?.content ?? '');
const reasons = [...(source.p4_review_reasons || [])];

function canonical(value) {
  return String(value ?? '')
    .replace(/[\u200B-\u200F\u2060\uFEFF]/gu, '')
    .replace(/\*+/g, '')
    .replace(/[“”]/gu, '"')
    .replace(/[‘’]/gu, "'")
    .replace(/[–—]/gu, '-')
    .replace(/\s+/gu, ' ')
    .trim()
    .toLocaleLowerCase('en');
}

function isInsideCandidateBoundary(candidateQuote, evidenceQuote) {
  const candidate = canonical(candidateQuote);
  const evidence = canonical(evidenceQuote);
  return Boolean(candidate && evidence && candidate.includes(evidence));
}

function isSupportedCountryName(name) {
  const normalized = canonical(name);
  const allowedStateNames = new Set([
    'united states',
    'state of palestine',
    'vatican city state',
    'federated states of micronesia',
  ]);
  return !/\bstate$/u.test(normalized) || allowedStateNames.has(normalized);
}

function isNameExplicit(name, evidenceQuote) {
  return canonical(evidenceQuote).includes(canonical(name));
}

function correctedLevel(name, level) {
  const normalized = canonical(name);
  if (new Set(['gaza', 'gaza strip', 'falklands', 'falkland islands']).has(normalized)) return 'unknown';
  if (/^(?:northern|southern|eastern|western|central)\s+\p{Lu}/u.test(String(name ?? '').trim())) return 'unknown';
  return level;
}

function isInstitutionLabel(name) {
  return /\b(?:white house|parliament|ministry|government office|headquarters|court|council)\b/u.test(canonical(name));
}

function isActorOrMetonym(name) {
  const normalized = canonical(name);
  return (source.p4_actors || []).some((actor) => canonical(actor?.name) === normalized);
}

function isActorAffiliation(name, evidenceQuote) {
  const evidence = canonical(evidenceQuote);
  const affiliation = /\b(?:officials?|delegates?|representatives?)\s+from\s+([^.;]+?)(?=\s+(?:on|who|held|met|during)\b|,\s+and\b|[.;]|$)/gu;
  return [...evidence.matchAll(affiliation)]
    .some((match) => canonical(match[1]).includes(canonical(name)));
}

function isNeighboringVisitLocation(name, evidenceQuote) {
  const evidence = canonical(evidenceQuote);
  const location = canonical(name).replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
  return new RegExp(`\\band that\\b[^.]*\\bvisit(?:s|ed|ing)?\\b[^.]*\\b${location}\\b`, 'u').test(evidence);
}

function isExactArticleQuote(quote) {
  const text = String(quote ?? '').trim();
  return Boolean(text
    && !/\.\.\.|…/u.test(text)
    && String(source.cleaned_content_text ?? '').includes(text));
}

function unwrap(value) {
  const text = String(value ?? '').trim();
  if ((text.startsWith('```') || text.startsWith('~~~'))
      && (text.endsWith('```') || text.endsWith('~~~'))) {
    const firstLine = text.indexOf('\n');
    const closing = Math.max(text.lastIndexOf('```'), text.lastIndexOf('~~~'));
    return text.slice(firstLine + 1, closing).trim();
  }
  return text;
}

let parsed;
try { parsed = JSON.parse(unwrap(raw)); } catch { parsed = null; }

const locations = [];
if (!parsed || !Array.isArray(parsed.locations)) {
  reasons.push(raw
    ? 'The location response was not valid JSON with a locations array.'
    : 'The location request failed or returned no response.');
} else {
  for (const value of parsed.locations) {
    const name = String(value?.name ?? '').trim();
    const level = value?.level;
    const evidenceQuote = String(value?.evidence_quote ?? '').trim();
    if (!name || !['country', 'admin1', 'city_regency', 'unknown'].includes(level)
        || !isExactArticleQuote(evidenceQuote)) {
      reasons.push('A proposed location was incomplete, truncated, or unsupported and was omitted.');
      continue;
    }
    if (!isInsideCandidateBoundary(source.candidate_evidence_quote, evidenceQuote)) {
      reasons.push('A proposed location used evidence outside the candidate event boundary and was omitted.');
      continue;
    }
    if (!isNameExplicit(name, evidenceQuote)) {
      reasons.push('A proposed location name was not explicit in its own evidence and was omitted.');
      continue;
    }
    if (isInstitutionLabel(name)) {
      reasons.push('A proposed location was an institution rather than a supported geographic place and was omitted.');
      continue;
    }
    if (isActorOrMetonym(name)) {
      reasons.push('A proposed location was acting as an actor or metonym rather than identifying where the event occurred and was omitted.');
      continue;
    }
    if (isActorAffiliation(name, evidenceQuote)) {
      reasons.push('A proposed location described an actor affiliation rather than where the event occurred and was omitted.');
      continue;
    }
    if (isNeighboringVisitLocation(name, evidenceQuote)) {
      reasons.push('A proposed location belonged to a neighboring event clause rather than the candidate event and was omitted.');
      continue;
    }
    if (level === 'country' && !isSupportedCountryName(name)) {
      reasons.push('A proposed country was not a supported country name and was omitted.');
      continue;
    }
    const location = {name, level: correctedLevel(name, level), evidence_quote: evidenceQuote};
    if (!locations.some((existing) => JSON.stringify(existing) === JSON.stringify(location))) {
      locations.push(location);
    }
  }
}

return [{json: {
  ...source,
  p4_location_candidates: locations,
  p4_location_raw_output: raw || null,
  p4_review_reasons: reasons,
}}];

const s=$('Validate Locations').item.json;
const raw=String($json?.choices?.[0]?.message?.content??'');
const reasons=[...(s.p4_review_reasons||[])],src=s.p4_location_candidates||[],accepted=[];
const unwrap=x=>{const t=String(x??'').trim();if((t.startsWith('```')||t.startsWith('~~~'))&&(t.endsWith('```')||t.endsWith('~~~'))){const a=t.indexOf('\n'),b=Math.max(t.lastIndexOf('```'),t.lastIndexOf('~~~'));return t.slice(a+1,b).trim()}return t};
let status='NOT_RUN';
if(src.length){
  let p;try{p=JSON.parse(unwrap(raw))}catch{p=null}
  status='ACCEPT';
  const seen=new Set();
  if(!p||!Array.isArray(p.decisions)){status='FAILED';reasons.push('The location safeguard failed or returned no usable decisions; unreviewed locations were omitted.')}
  else{
    for(const d of p.decisions){
      const validIndex=Number.isInteger(d?.index)&&d.index>=0&&d.index<src.length&&!seen.has(d.index);
      const validDecision=['ACCEPT','REJECT'].includes(d?.decision);
      const validReason=d?.decision==='ACCEPT'?d?.reason==null:typeof d?.reason==='string'&&d.reason.trim();
      if(!validIndex||!validDecision||!validReason){status='FAILED';continue}
      seen.add(d.index);
      if(d.decision==='ACCEPT')accepted.push(src[d.index]);
      else{if(status!=='FAILED')status='REJECT';reasons.push('The location safeguard rejected a location: '+d.reason.trim())}
    }
    const missing=src.length-seen.size;
    if(missing>0){status='FAILED';reasons.push('The location safeguard returned incomplete decisions; '+missing+' unreviewed location'+(missing===1?' was':'s were')+' omitted.')}
    else if(status==='FAILED')reasons.push('The location safeguard returned invalid or duplicate decisions; only individually approved locations were retained.')
  }
}
return [{json:{...s,p4_locations:accepted,p4_location_safeguard_status:status,p4_location_safeguard_raw_output:raw||null,p4_review_reasons:reasons}}];
